			regs.setValue(snap0,
				new RegisterValue(lang.getRegister("RBX"), BigInteger.valueOf(0x0)));
			regs.setValue(snap0,
				new RegisterValue(lang.getRegister("RCX"), BigInteger.valueOf(5)));
			regs.setValue(snap0,
				new RegisterValue(lang.getRegister("RDX"), BigInteger.valueOf(0x80)));

			regs.setValue(snap1,
